def orbit_cells(r,c,n=30):
 seen={(r,c)}; stack=[(r,c)]
 while stack:
  a,b=stack.pop()
  cand=[(b,a)]
  if 2 <= a < n: cand.append((31-a,b))
  if 2 <= b < n: cand.append((a,31-b))
  for x in cand:
   if 0<=x[0]<n and 0<=x[1]<n and x not in seen:
    seen.add(x);stack.append(x)
 return seen
